import { readFileSync } from 'node:fs'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

class Fail extends Error {}

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  const r = { scheme: m[1], path: m[3], query: m[4], fragment: m[5] }
  if (m[2] !== undefined) {
    let a = m[2]
    const at = a.lastIndexOf('@')
    if (at >= 0) { r.userinfo = a.slice(0, at); a = a.slice(at + 1) }
    const colon = a.indexOf(':', a.lastIndexOf(']') + 1)
    if (colon >= 0) { r.port = a.slice(colon + 1); a = a.slice(0, colon) }
    r.host = a
  }
  return r
}

function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s, name) {
  if (s === undefined) return s
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new Fail(`the ${name} has a truncated percent-encoding`)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const lower = s => s.replace(/[A-Z]/g, c => c.toLowerCase())

function normalize(r, line) {
  const check = (v, n) => { if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) throw new Fail(`line ${line}: the ${n} has a truncated percent-encoding`) }
  check(r.path, 'path'); check(r.userinfo, 'userinfo'); check(r.host, 'host'); check(r.query, 'query'); check(r.fragment, 'fragment')
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  const hasAuth = r.host !== undefined
  let path = removeDots(pct(r.path, 'path'))
  const userinfo = pct(r.userinfo, 'userinfo')
  const host = hasAuth ? lower(pct(r.host, 'host')) : undefined
  let port = r.port
  if (port === '' || (port !== undefined && scheme !== undefined && DEFAULT_PORTS[scheme] === port)) port = undefined
  if (hasAuth && path === '') path = '/'
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (hasAuth) {
    out += '//'
    if (userinfo !== undefined) out += userinfo + '@'
    out += host
    if (port !== undefined) out += ':' + port
  }
  out += path
  const q = pct(r.query, 'query'), f = pct(r.fragment, 'fragment')
  if (q !== undefined) out += '?' + q
  if (f !== undefined) out += '#' + f
  return out
}

function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, fragment: ref.fragment }
  const copyAuth = () => { t.userinfo = base.userinfo; t.host = base.host; t.port = base.port }
  if (ref.host !== undefined) {
    t.userinfo = ref.userinfo; t.host = ref.host; t.port = ref.port
    t.path = removeDots(ref.path); t.query = ref.query
  } else {
    copyAuth()
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.host !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((l, i) => {
      const n = i + 1
      if (args[0] === 'normalize') { out.push(normalize(parse(l), n)); return }
      const sp = l.indexOf(' ')
      if (sp < 0) throw new Fail(`line ${n}: expected a base and a reference`)
      const base = parse(l.slice(0, sp))
      if (base.scheme === undefined) throw new Fail(`line ${n}: the base has no scheme`)
      out.push(normalize(resolve(base, parse(l.slice(sp + 1))), n))
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write('error: ' + e.message + '\n')
    process.exit(2)
  }
  process.stdout.write(out.map(x => x + '\n').join(''))
}
main()
