/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scanner.js'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  fail('usage: cli.js tokens|stats')
}

const source = readFileSync(0).toString('utf8')
let tokens
try {
  tokens = scan(source)
} catch (e) {
  if (e instanceof ScanError) fail(`${e.line}:${e.column}: ${e.reason}`)
  throw e
}

let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.column} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
"}

