  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isWord = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

export function scan(source) {
  const cs = Array.from(source)
  const n = cs.length
  // position of every code point (plus end)
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l
    cols[i] = c
    if (cs[i] === '\n') {
      l++
      c = 1
    } else if (cs[i] === '\t') c = (Math.floor((c - 1) / 4) + 1) * 4 + 1
    else c++
  }
  lines[n] = l
  cols[n] = c
  const err = (i, reason) => new ScanError(lines[i], cols[i], reason)

  const tokens = []
  let i = 0
  const push = (start, kind, body) => tokens.push({ line: lines[start], column: cols[start], kind, body })

  // digit run of a radix test; underscore only between two digits
  function run(j, test) {
    if (!test(cs[j])) return j
    j++
    for (;;) {
      if (test(cs[j])) j++
      else if (cs[j] === '_' && test(cs[j - 1]) && test(cs[j + 1])) j += 2
      else return j
    }
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      i++
    } else if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
    } else if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (depth > 0) {
        if (i >= n) throw err(start, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') {
          depth++
          i += 2
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          depth--
          i += 2
        } else i++
      }
    } else if (ch === 'r' && cs[i + 1] === '"') {
      const start = i
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw err(start, 'unterminated string')
      push(start, 'rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
    } else if (isLetter(ch) || ch === '_') {
      let j = i + 1
      while (isWord(cs[j])) j++
      const text = cs.slice(i, j).join('')
      push(i, KEYWORDS.has(text) ? 'keyword' : 'ident', text)
      i = j
    } else if (isDigit(ch)) {
      let j = i + 1
      const p = cs[i + 1]
      let bad = false
      if (ch === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        const lp = p.toLowerCase()
        const test = lp === 'x' ? isHex : lp === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        j = i + 2
        const e = run(j, test)
        if (e === j) bad = true
        j = e
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) j = run(j + 1, isDigit)
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (isWord(cs[j])) bad = true
      if (bad) {
        while (isWord(cs[j])) j++
        throw err(i, `invalid number ${cs.slice(i, j).join('')}`)
      }
      push(i, 'number', cs.slice(i, j).join(''))
      i = j
    } else if (ch === '"') {
      const start = i
      let j = i + 1
      let value = ''
