import { readFileSync } from 'node:fs'
import { UriError, parse, check, normalize, resolve, serialize } from './uri.js'

const mode = process.argv.length === 3 ? process.argv[2] : undefined
if (mode !== 'normalize' && mode !== 'resolve') {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const out = []
try {
  lines.forEach((line, idx) => {
    try {
      if (mode === 'normalize') {
        const r = parse(line)
        check(r)
        out.push(serialize(normalize(r)))
      } else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new UriError('expected a base and a reference')
        const base = parse(line.slice(0, sp))
        if (base.scheme === undefined) throw new UriError('the base has no scheme')
        const ref = parse(line.slice(sp + 1))
        check(base)
        check(ref)
        out.push(serialize(normalize(resolve(base, ref))))
      }
    } catch (e) {
      if (e instanceof UriError) throw new UriError(`line ${idx + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
