    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function serialize(r) {
  let s = ''
  if (r.scheme !== undefined) s += r.scheme + ':'
  if (r.host !== undefined) {
    s += '//'
    if (r.userinfo !== undefined) s += r.userinfo + '@'
    s += r.host
    if (r.port !== undefined) s += ':' + r.port
  }
  s += r.path
  if (r.query !== undefined) s += '?' + r.query
  if (r.fragment !== undefined) s += '#' + r.fragment
  return s
}

export function normalize(r) {
  const n = { ...r }
  if (n.scheme !== undefined) n.scheme = lower(n.scheme)
  n.path = pct(n.path)
  n.query = pct(n.query)
  n.fragment = pct(n.fragment)
  if (n.host !== undefined) {
    n.userinfo = pct(n.userinfo)
    n.host = pct(n.host).replace(/(%[0-9A-F]{2})|[A-Z]/g, (m, p) => (p ? m : m.toLowerCase()))
