function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  return docs
}

function diff(base, side) {
  const n = base.length
  const m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const changes = []
  let i = 0
  let j = 0
  let bs = 0
  let ss = 0
  const flush = () => {
    if (i > bs || j > ss) changes.push({ bs, be: i, ss, se: j, lines: side.slice(ss, j) })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++
      j++
      bs = i
      ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n
  j = m
  flush()
  return changes
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  let input = ''
  try {
    input = require('node:fs').readFileSync(0, 'utf8')
  } catch {}
  const docs = parse(input)
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const changes = [
    ...diff(base, mine).map(c => ({ ...c, side: 0 })),
    ...diff(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  changes.sort((a, b) => a.bs - b.bs || a.side - b.side)

  const regions = [] // {type, lines} or conflict
  let pos = 0
  let k = 0
  while (k < changes.length) {
    const rs = changes[k].bs
    let re = changes[k].be
    const group = [changes[k++]]
    while (k < changes.length && changes[k].bs <= re) {
      re = Math.max(re, changes[k].be)
      group.push(changes[k++])
    }
    if (rs > pos) regions.push({ type: 'stable', lines: base.slice(pos, rs) })
    pos = re
    if (group.length === 1) {
      regions.push({ type: group[0].side === 0 ? 'mine' : 'theirs', lines: group[0].lines })
      continue
    }
    const baseLines = base.slice(rs, re)
    const rep = side => {
      const cs = group.filter(c => c.side === side)
      if (!cs.length) return baseLines
      const src = side === 0 ? mine : theirs
      const minB = Math.min(...cs.map(c => c.bs))
      const maxB = Math.max(...cs.map(c => c.be))
      const s = Math.min(...cs.map(c => c.ss)) - (minB - rs)
      const e = Math.max(...cs.map(c => c.se)) + (re - maxB)
      return src.slice(s, e)
    }
    const m = rep(0)
    const t = rep(1)
    if (eq(m, t)) regions.push({ type: 'both', lines: m })
    else if (eq(m, baseLines)) regions.push({ type: 'theirs', lines: t })
    else if (eq(t, baseLines)) regions.push({ type: 'mine', lines: m })
    else regions.push({ type: 'conflict', mine: m, base: baseLines, theirs: t })
  }
  if (pos < base.length) regions.push({ type: 'stable', lines: base.slice(pos) })

  const out = []
  let conflict = false
  for (const r of regions) {
    if (r.type === 'conflict') conflict = true
    if (mode === 'regions') {
      out.push(
        r.type === 'conflict'
          ? `conflict mine=${r.mine.length} base=${r.base.length} theirs=${r.theirs.length}`
          : `${r.type} ${r.lines.length}`,
      )
    } else if (r.type === 'conflict') {
      out.push('<<<<<<< mine', ...r.mine)
      if (mode === 'merge') out.push('||||||| base', ...r.base)
      out.push('=======', ...r.theirs, '>>>>>>> theirs')
    } else out.push(...r.lines)
  }
  process.stdout.write(out.map(l => `${l}\n`).join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
