#!/usr/bin/env node
import { readFileSync } from 'node:fs'

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let prev = null
  let lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const bad = (m) => new Fail(`line ${i + 1}: ${m}`)
    const int = (v, field, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) throw bad(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = t[0]
    if (d === 'bucket' || d === 'window') {
      const n = d === 'bucket' ? 5 : 4
      if (t.length !== n) throw bad(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      if (events.length) throw bad('declarations must come before the first event')
      if (!NAME.test(t[1])) throw bad(`invalid policy name ${t[1]}`)
      let p
      if (d === 'bucket') {
        const capacity = int(t[2], 'capacity', 1), refill = int(t[3], 'refill', 0), per = int(t[4], 'per', 1)
        p = { kind: 'bucket', name: t[1], capacity, refill, per }
      } else {
        const limit = int(t[2], 'limit', 0), span = int(t[3], 'span', 1)
        p = { kind: 'window', name: t[1], limit, span }
      }
      if (policies.has(t[1])) throw bad(`policy ${t[1]} is declared twice`)
      policies.set(t[1], p)
    } else if (d === 'route') {
      if (t.length < 3) throw bad('expected route <prefix> <policy>...')
      if (events.length) throw bad('declarations must come before the first event')
      if (!NAME.test(t[1])) throw bad(`invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) throw bad(`prefix ${t[1]} is routed twice`)
      const list = []
      for (const n of t.slice(2)) {
        if (!policies.has(n)) throw bad(`unknown policy ${n}`)
        list.push(policies.get(n))
      }
      routes.set(t[1], list)
    } else if (d === 'event') {
      if (t.length !== 3) throw bad('expected event <tick> <key>')
      const tick = int(t[1], 'tick', 0)
      if (!NAME.test(t[2])) throw bad(`invalid key ${t[2]}`)
      if (prev !== null && tick < prev) throw bad(`tick ${tick} is before tick ${prev}`)
      prev = tick
      events.push({ tick, key: t[2] })
    } else {
      throw bad(`unknown directive ${d}`)
    }
  }
  return { routes, events }
}

function run(mode, text) {
  const { routes, events } = parse(text)
  const states = new Map() // policy -> Map key -> state
  const stateOf = (p, key, tick) => {
    let m = states.get(p)
    if (!m) states.set(p, (m = new Map()))
    let s = m.get(key)
    if (!s) {
      s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
      m.set(key, s)
    }
    return s
  }
  const out = []
  const counts = new Map()
  let ta = 0, td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const [pre, list] of routes) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    let denier = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const s = stateOf(p, key, tick)
        if (p.kind === 'bucket') {
          const cap = p.capacity * p.per
          s.num += p.refill * (tick - s.last)
          if (s.num > cap) s.num = cap
          s.last = tick
        } else {
          const cut = tick - p.span
          s.ticks = s.ticks.filter((x) => x > cut)
        }
        return s
      })
      for (let j = 0; j < list.length; j++) {
        const p = list[j], s = sts[j]
        const ok = p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) { denier = p.name; break }
      }
      if (denier === null) {
        list.forEach((p, j) => {
          if (p.kind === 'bucket') sts[j].num -= p.per
          else sts[j].ticks.push(tick)
        })
      }
    }
    const c = counts.get(key) || { a: 0, d: 0 }
    if (denier === null) { c.a++; ta++ } else { c.d++; td++ }
    counts.set(key, c)
    out.push(denier === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denier}`)
  }
  if (mode === 'replay') return out
  const res = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)).map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
  res.push(`total allowed=${ta} denied=${td}`)
  return res
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
try {
  const lines = run(args[0], readFileSync(0, 'utf8'))
  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
