import { readFileSync } from 'node:fs'

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && /^[0-9]$/.test(c)
const isIdent = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  while (i < n) {
    const c = s[i]
    const sl = line
    const sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && s[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isLetter(c) || c === '_') {
      let w = ''
      while (i < n && isIdent(s[i])) w += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(w) ? 'keyword' : 'ident', body: w })
      continue
    }
    if (isDigit(c)) {
      let w = ''
      const take = () => { w += adv() }
      // digit run with single underscores between digits
      const run = (pred) => {
        let any = false
        while (i < n) {
          if (pred(s[i])) { take(); any = true }
          else if (s[i] === '_' && any && pred(s[i - 1]) && pred(s[i + 1])) take()
          else break
        }
        return any
      }
      let bad = false
      const p = s[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        take(); take()
        const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? (d) => d === '0' || d === '1' : (d) => d !== undefined && /^[0-7]$/.test(d)
        if (!run(pred)) bad = true
      } else {
        run(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) { take(); run(isDigit) }
        if ((s[i] === 'e' || s[i] === 'E') &&
          (isDigit(s[i + 1]) || ((s[i + 1] === '+' || s[i + 1] === '-') && isDigit(s[i + 2])))) {
          take()
          if (!isDigit(s[i])) take()
          run(isDigit)
        }
      }
      if (bad || isIdent(s[i])) {
        while (i < n && isIdent(s[i])) take()
        throw new ScanError(sl, sc, `invalid number ${w}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: w })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = s[i]
        if (d === '"') { adv(); break }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') { v += adv(); continue }
        const el = line
        const ec = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = s[i]
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.prototype.hasOwnProperty.call(simple, e)) { adv(); v += simple[e]; continue }
        if (e === 'x') {
          if (!(isHex(s[i + 1]) && isHex(s[i + 2]))) throw bad()
          adv()
          const h = adv() + adv()
          v += String.fromCodePoint(parseInt(h, 16))
          continue
        }
        if (e === 'u') {
          if (s[i + 1] !== '{') throw bad()
          let j = i + 2
          let h = ''
          while (isHex(s[j])) h += s[j++]
          if (!h || s[j] !== '}') throw bad()
          const t = h.replace(/^0+/, '')
          if (t.length > 6 || (t && parseInt(t, 16) > 0x10ffff)) throw bad()
          while (i <= j) adv()
          v += String.fromCodePoint(t ? parseInt(t, 16) : 0)
          continue
        }
        throw bad()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (s[i + 1] ?? '')
    if (PUNCT2.includes(two)) {
      adv(); adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: c })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const mode = process.argv.length === 3 ? process.argv[2] : undefined
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let tokens
try {
  tokens = scan(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (mode === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
    out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  }
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
