import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
let candidates = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (candidates !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    candidates = seen
  } else if (t[0] === 'ballot') {
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!candidates || !candidates.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
}
if (candidates === null) fail('error: no candidates')

const continuing = new Set(candidates)
const history = [] // Map per round
const out = []
let winner = null
for (;;) {
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  history.push(counts)
  const sorted = [...counts.keys()].sort((a, b) => {
    const d = counts.get(b) - counts.get(a)
    return d > 0n ? 1 : d < 0n ? -1 : a < b ? -1 : a > b ? 1 : 0
  })
  out.push(`round ${history.length}: ${sorted.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) break
  const win = sorted.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) { winner = win; break }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let tied = [...counts.keys()].filter((c) => counts.get(c) === min)
  for (let r = 0; r < history.length && tied.length > 1; ) {
    let lo = null
    let allEq = true
    for (const c of tied) {
      const v = history[r].get(c)
      if (lo !== null && v !== lo) allEq = false
      if (lo === null || v < lo) lo = v
    }
    if (allEq) { r++; continue }
    tied = tied.filter((c) => history[r].get(c) === lo)
    r = 0
  }
  const elim = tied.reduce((a, b) => (a > b ? a : b))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.filter((l) => !l.startsWith('eliminated') || true).join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
EOF
