{"file_path":"src/render.js","content":"function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function ser(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  switch (node.t) {
    case 'table': {
      const ks = sortedKeys(node)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${ser(node.map.get(k), indent + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!node.items.length) return '[]'
      return '[\n' + node.items.map((v) => pad + ser(v, indent + 1)).join(',\n') + '\n' + end + ']'
    default:
      return JSON.stringify(node.v)
  }
}

export function renderJson(root) {
  return ser(root, 0) + '\n'
}

export function renderKeys(root) {
  const lines = []
  const visit = (node, path) => {
    if (path !== null) lines.push(`${path} ${node.t === 'scalar' ? node.type : node.t}`)
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) visit(node.map.get(k), path === null ? k : `${path}.${k}`)
    } else if (node.t === 'array') {
      node.items.forEach((v, i) => visit(v, `${path}[${i}]`))
    }
  }
  visit(root, null)
  return lines.length ? lines.join('\n') + '\n' : ''
}
