function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ bs, be: i, ss, se: j, who })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return res
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const regions = []
  let conflict = false
  let pos = 0, k = 0
  while (k < all.length) {
    const start = all[k].bs
    let end = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    if (start > pos) regions.push({ kind: 'stable', lines: base.slice(pos, start) })
    pos = end
    if (group.length === 1) {
      const c = group[0]
      const lines = (c.who === 0 ? mine : theirs).slice(c.ss, c.se)
      regions.push({ kind: c.who === 0 ? 'mine' : 'theirs', lines })
      continue
    }
    const baseL = base.slice(start, end)
    const sideLines = (who, arr) => {
      const g = group.filter(c => c.who === who)
      if (!g.length) return baseL
      const minB = Math.min(...g.map(c => c.bs)), maxB = Math.max(...g.map(c => c.be))
      const s = Math.min(...g.map(c => c.ss)) - (minB - start)
      const e = Math.max(...g.map(c => c.se)) + (end - maxB)
      return arr.slice(s, e)
    }
    const m = sideLines(0, mine), t = sideLines(1, theirs)
    if (same(m, t)) regions.push({ kind: 'both', lines: m })
    else if (same(m, baseL)) regions.push({ kind: 'theirs', lines: t })
    else if (same(t, baseL)) regions.push({ kind: 'mine', lines: m })
    else {
      conflict = true
      regions.push({ kind: 'conflict', mine: m, base: baseL, theirs: t })
    }
  }
  if (pos < base.length) regions.push({ kind: 'stable', lines: base.slice(pos) })
  return { regions, conflict }
}
