import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })

function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row, key: L + row, L }
}
const colKey = (c) => c

// ---- read sheet
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map() // key -> {col,row,key,content}
for (let i = 0; i < lines.length; i++) {
  let s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const raw = m[0]
