        case '+': return fin(x.v + y.v)
        case '-': return fin(x.v - y.v)
        case '*': return fin(x.v * y.v)
        case '/': return y.v === 0 ? err('#DIV/0!') : fin(x.v / y.v)
        case '^': return fin(Math.pow(x.v, y.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = evalNode(args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return evalNode(truth ? args[1] : args[2])
  }
  if (name === 'ABS' ? args.length !== 1 : args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.type === 'range') vals.push(...rangeValues(a))
    else vals.push(evalNode(a))
  }
  const e = vals.find((v) => v.t === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'ABS': return num(Math.abs(nums[0]))
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s), Infinity))
    case 'MAX': return num(nums.reduce((s, x) => (x > s ? x : s), -Infinity))
    case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
  return err('#ERR!')
}

function fmt(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const out = []
for (const cell of order) {
  if (mode === 'values') out.push(`${cell.key}=${fmt(cellValue(cell.key))}`)
  else {
    let line = cell.key + ':'
    if (cell.content[0] === '=') {
      const ast = formulaOf(cell)
      if (ast) {
        const m = new Map()
        walkDeps(ast, m)
        const ds = [...m.values()].sort((x, y) => x.col - y.col || x.row - y.row)
        for (const d of ds) line += ' ' + d.key
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
EOF
