import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const word = t[0]
  if (word === 'candidates') {
    if (cands !== null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = t.slice(1)
  } else if (word === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${word}`)
  }
})
if (cands === null) fail('error: no candidates')

const continuing = new Set(cands)
const history = [] // Map name -> count per round
const out = []
let winner = null
for (let k = 1; ; k++) {
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  history.push(counts)
  const sorted = [...counts].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : 1))
  let line = `round ${k}: ` + sorted.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const win = sorted.find(([, v]) => v * 2n > active)
  if (win) { winner = win[0]; break }
  let tied = [...continuing]
  let min = sorted[sorted.length - 1][1]
  tied = tied.filter((c) => counts.get(c) === min)
  for (let r = 0; r < history.length && tied.length > 1; r++) {
    const vals = tied.map((c) => history[r].get(c))
    const m = vals.reduce((a, b) => (b < a ? b : a))
    if (vals.some((v) => v !== m)) {
      tied = tied.filter((c) => history[r].get(c) === m)
      r = -1
    }
  }
  const elim = tied.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
EOF
