{"command":"cat > src/cli.js <<'EOF'
#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(message, code = 2) {
    super(message)
    this.code = code
  }
}

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const NAME = /^[A-Za-z0-9_.-]+$/
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parseArgs(argv) {
  const [mode, ...rest] = argv
  if (mode === 'waves' || mode === 'explain') {
    if (rest.length) throw new Fail(USAGE)
    return { mode }
  }
  if (mode === 'pack' && rest.length === 1) {
    if (!/^[1-9][0-9]*$/.test(rest[0])) throw new Fail('error: workers must be a positive integer')
    return { mode, workers: Number(rest[0]) }
  }
  throw new Fail(USAGE)
}

function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map() // name -> cost (BigInt)
  const deps = [] // [name, dependency] in input order
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      for (const d of w.slice(2)) deps.push([w[1], d])
      if (!deps.length) return
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  const names = []
  for (const [a, b] of deps) {
    for (const x of [a, b]) if (!tasks.has(x)) throw new Fail(`error: unknown task ${x}`)
  }
  const depSets = new Map()
  for (const k of tasks.keys()) depSets.set(k, new Set())
  for (const [a, b] of deps) depSets.get(a).add(b)
  const dependsOn = new Map()
  const sorted = [...tasks.keys()].sort(cmp)
  for (const k of sorted) dependsOn.set(k, [...depSets.get(k)].sort(cmp))
  void names
  return { tasks, sorted, dependsOn }
}

function findCycle({ sorted, dependsOn }) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of dependsOn.get(u)) {
      if (state.get(v) === 1) return [...stack.slice(stack.indexOf(v)), v]
      if (!state.has(v)) {
        const c = visit(v)
        if (c) return c
      }
    }
    stack.pop()
    state.set(u, 2)
    return null
  }
  for (const k of sorted) {
    if (!state.has(k)) {
      const c = visit(k)
      if (c) return c
    }
  }
  return null
}

function timing(g) {
  const info = new Map()
  const visit = (u) => {
    if (info.has(u)) return info.get(u)
    let start = 0n
    let depth = 0
    for (const d of g.dependsOn.get(u)) {
      const x = visit(d)
      if (x.finish > start) start = x.finish
      if (x.depth + 1 > depth) depth = x.depth + 1
    }
    const r = { start, finish: start + g.tasks.get(u), depth }
    info.set(u, r)
    return r
  }
  let total = 0n
  for (const k of g.sorted) {
    const r = visit(k)
    if (r.finish > total) total = r.finish
  }
  return { info, total }
}

function priorities(g) {
  const dependents = new Map(g.sorted.map((k) => [k, []]))
  for (const k of g.sorted) for (const d of g.dependsOn.get(k)) dependents.get(d).push(k)
  const pri = new Map()
  const visit = (u) => {
    if (pri.has(u)) return pri.get(u)
    let best = 0n
    for (const v of dependents.get(u)) {
      const p = visit(v)
      if (p > best) best = p
    }
    const r = g.tasks.get(u) + best
    pri.set(u, r)
    return r
  }
  for (const k of g.sorted) visit(k)
  return pri
}

function pack(g, workers) {
  const pri = priorities(g)
  const finish = new Map()
  const free = new Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let remaining = g.sorted.length
  let t = 0n
  while (remaining > 0) {
    for (;;) {
      const w = free.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const k of g.sorted) {
