    state.set(u, 1)
    stack.push(u)
    for (const v of dependsOn.get(u)) {
      if (state.get(v) === 1) return [...stack.slice(stack.indexOf(v)), v]
      if (!state.has(v)) {
        const c = visit(v)
        if (c) return c
      }
    }
    stack.pop()
    state.set(u, 2)
    return null
  }
  for (const k of sorted) {
    if (!state.has(k)) {
      const c = visit(k)
      if (c) return c
    }
  }
