    let best = null
    for (const p of routes.keys()) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    let denier = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const id = p.name + '\0' + key
        let s = states.get(id)
        if (!s) {
          s = p.type === 'bucket' ? { v: p.cap * p.per, at: tick } : { ticks: [] }
          states.set(id, s)
        }
        if (p.type === 'bucket') {
          s.v += p.refill * (tick - s.at)
          s.at = tick
          const m = p.cap * p.per
          if (s.v > m) s.v = m
        } else {
          s.ticks = s.ticks.filter((t) => t > tick - p.span)
        }
        return s
      })
      for (let i = 0; i < list.length; i++) {
        const p = list[i], s = sts[i]
        const ok = p.type === 'bucket' ? s.v >= p.per : BigInt(s.ticks.length) < p.limit
