    if (!st) stats.set(key, (st = { a: 0, d: 0 }))
    if (denier) { st.d++; totD++; out.push(`${tickStr} ${key} deny ${denier.name}`) }
    else { st.a++; totA++; out.push(`${tickStr} ${key} allow`) }
  }

  try {
    for (let i = 0; i < lines.length; i++) {
      const t = lines[i].trim()
      if (t === '' || t.startsWith('#')) continue
      try { handle(t.split(/\s+/)) } catch (e) {
        if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
        throw e
      }
    }
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }

  let res
  if (mode === 'replay') res = out
  else {
    res = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)).map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
    res.push(`total allowed=${totA} denied=${totD}`)
  }
  process.stdout.write(res.length ? res.join('\n') + '\n' : '')
}

main()
