  if (idx <= 26) return String.fromCharCode(64 + idx)
  const hi = Math.floor((idx - 1) / 26)
  const lo = ((idx - 1) % 26) + 1
  return String.fromCharCode(64 + hi) + String.fromCharCode(64 + lo)
}
function cmpAddr(a, b) {
  return a.colIdx - b.colIdx || a.row - b.row
}
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

// ---------- sheet parsing ----------
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') continue
  let j = 0
  while (j < line.length && line[j] !== ' ' && line[j] !== '\t') j++
  const word = line.slice(0, j)
  while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
  const content = line.slice(j)
  const a = parseAddr(word)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  cells.set(a.key, { addr: a, content })
}

// ---------- formula parsing ----------
const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
class ParseError extends Error {}

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^():,])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else throw new ParseError()
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) throw new ParseError(); p++ }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new ParseError()
    const tk = toks[p]
    if (tk.t === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.t === 'op') {
      if (tk.v === '(') {
        p++
        const e = cmp()
        expect(')')
        return { t: 'paren', e }
      }
      throw new ParseError()
    }
    p++
    const name = tk.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          break
        }
      }
      expect(')')
      return { t: 'call', name, args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') throw new ParseError()
      const w2 = toks[p++].v
      return { t: 'range', a: parseAddr(tk.v), b: parseAddr(w2) }
    }
    if (name === 'TRUE') return { t: 'bool', v: true }
    if (name === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', a: parseAddr(tk.v) }
  }
  const e = cmp()
  if (p !== toks.length) throw new ParseError()
  return e
}

// ---------- values ----------
const num = (n) => ({ k: 'n', v: n })
const err = (e) => ({ k: 'e', v: e })
const isErr = (x) => x.k === 'e'

function literal(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRS.includes(content)) return err(content)
  return { k: 's', v: content }
}

function toNum(x) {
  if (x.k === 'n') return x
  if (x.k === 'b') return num(x.v ? 1 : 0)
  if (x.k === 's') return err('#VALUE!')
  return x
}
function finite(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 's') {
    const x = Array.from(a.v), y = Array.from(b.v)
    const n = Math.min(x.length, y.length)
    for (let i = 0; i < n; i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  const x = a.k === 'b' ? (a.v ? 1 : 0) : a.v
  const y = b.k === 'b' ? (b.v ? 1 : 0) : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

const parsed = new Map()
const cache = new Map()
const inProgress = new Set()

function getParsed(key) {
  if (!parsed.has(key)) {
    const c = cells.get(key)
    let r = null
    try { r = parseFormula(c.content.slice(1)) } catch (e) { if (!(e instanceof ParseError)) throw e }
    parsed.set(key, r)
  }
  return parsed.get(key)
}

function cellValue(a) {
  if (!a) return err('#REF!')
  const key = a.key
  const c = cells.get(key)
  if (!c) return num(0)
  if (cache.has(key)) return cache.get(key)
  if (inProgress.has(key)) return err('#CYCLE!')
  let v
  if (c.content[0] === '=') {
    const ast = getParsed(key)
    if (!ast) v = err('#ERR!')
    else {
      inProgress.add(key)
      v = evalNode(ast)
      inProgress.delete(key)
    }
  } else v = literal(c.content)
  cache.set(key, v)
  return v
}

function rangeCells(r) {
  if (!r.a || !r.b) return null
  const c1 = Math.min(r.a.colIdx, r.b.colIdx), c2 = Math.max(r.a.colIdx, r.b.colIdx)
  const r1 = Math.min(r.a.row, r.b.row), r2 = Math.max(r.a.row, r.b.row)
  const out = []
  for (let c = c1; c <= c2; c++) for (let w = r1; w <= r2; w++) {
    const col = colName(c)
    out.push({ col, row: w, colIdx: c, key: col + w })
  }
  return out
}

function argValues(node) {
  if (node.t === 'range') {
    const cs = rangeCells(node)
    if (!cs) return [err('#REF!')]
    return cs.map(cellValue)
  }
  return [evalNode(node)]
}

function evalNode(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'paren': return evalNode(n.e)
    case 'ref': return cellValue(n.a)
    case 'range': return err('#ERR!')
    case 'neg': {
      const x = toNum(evalNode(n.e))
      if (isErr(x)) return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': return evalBin(n)
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalBin(n) {
  const l = evalNode(n.l)
  if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
    if (isErr(l)) return l
    const r = evalNode(n.r)
    if (isErr(r)) return r
    const c = compare(l, r)
    const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
    return { k: 'b', v: res }
  }
  const a = toNum(l)
  if (isErr(a)) return a
  const b = toNum(evalNode(n.r))
  if (isErr(b)) return b
  switch (n.op) {
    case '+': return finite(a.v + b.v)
    case '-': return finite(a.v - b.v)
    case '*': return finite(a.v * b.v)
    case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
    case '^': return finite(Math.pow(a.v, b.v))
  }
}

function evalCall(n) {
  const name = n.name
  const argc = n.args.length
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (argc !== 3) return err('#ERR!')
    const one = (node) => {
      const vs = argValues(node)
      return vs.length === 1 ? vs[0] : err('#ERR!')
    }
    const c = one(n.args[0])
    if (isErr(c)) return c
    let truth
    if (c.k === 'b') truth = c.v
    else if (c.k === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return one(n.args[truth ? 1 : 2])
  }
  if (name === 'ABS') {
    if (argc !== 1) return err('#ERR!')
    const vs = argValues(n.args[0])
    if (vs.length !== 1) return err('#ERR!')
    const x = toNum(vs[0])
    return isErr(x) ? x : num(Math.abs(x.v))
  }
  if (argc < 1) return err('#ERR!')
  const vals = []
  for (const a of n.args) for (const v of argValues(a)) vals.push(v)
  for (const v of vals) if (isErr(v)) return v
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
    case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    case 'MIN': return num(nums.reduce((m, x) => (x < m ? x : m), Infinity))
    case 'MAX': return num(nums.reduce((m, x) => (x > m ? x : m), -Infinity))
  }
}

// ---------- output ----------
function fmt(v) {
  switch (v.k) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function collectDeps(n, set) {
  switch (n.t) {
    case 'ref': if (n.a) set.set(n.a.key, n.a); break
    case 'range': {
      const cs = rangeCells(n)
      if (cs) for (const c of cs) set.set(c.key, c)
      break
    }
    case 'paren': case 'neg': collectDeps(n.e, set); break
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'call': for (const a of n.args) collectDeps(a, set); break
  }
}

const sorted = [...cells.values()].map((c) => c.addr).sort(cmpAddr)
let out = ''
for (const a of sorted) {
  if (mode === 'values') {
    out += `${a.key}=${fmt(cellValue(a))}\n`
  } else {
    const c = cells.get(a.key)
    let line = `${a.key}:`
    if (c.content[0] === '=') {
      const ast = getParsed(a.key)
      if (ast) {
        const set = new Map()
        collectDeps(ast, set)
        for (const d of [...set.values()].sort(cmpAddr)) line += ' ' + d.key
      }
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}
